import { isOptionAttribute } from "../../schema";
import type { Attr } from "./builders";

/**
 * Sprint 2-D.1 (TD-03) — visual examples for options, using the EXISTING `examples` metadata (no new
 * schema, no separate visual data): static SVG line art in public/visual (loaded lazily by the card
 * control), generated by scripts/generate-visual-assets.mjs. These attributes use the `cards` control;
 * values, IDs and prompt output are unchanged.
 */
export const VISUAL_ASSET_DIRS: Record<string, { dir: string; noun: { en: string; ko: string } }> = {
  "person.face.shape": { dir: "face-shape", noun: { en: "face shape", ko: "얼굴형" } },
  "person.eyes.shape": { dir: "eye-shape", noun: { en: "eye shape", ko: "눈 모양" } },
  "person.eyebrows.shape": { dir: "eyebrow-shape", noun: { en: "eyebrow shape", ko: "눈썹 모양" } },
};

export const VISUAL_PROVENANCE = {
  source: "Prompter original line art", // generated by scripts/generate-visual-assets.mjs
  license: "Project-owned",
  createdAt: "2026-11-25",
};

export const withVisualExamples = (attributes: Attr[]): Attr[] =>
  attributes.map((a) => {
    const asset = VISUAL_ASSET_DIRS[a.id];
    if (!asset || !isOptionAttribute(a)) return a;
    return {
      ...a,
      control: "cards",
      options: a.options.map((o) => ({
        ...o,
        examples: [
          {
            id: `${o.id}-line-art`,
            status: "ready" as const,
            src: `/visual/person/${asset.dir}/${o.id}.svg`,
            alt: { en: `Line drawing of a ${o.label.en.toLowerCase()} ${asset.noun.en}`, ko: `${o.label.ko} ${asset.noun.ko} 선화` },
            provenance: VISUAL_PROVENANCE,
          },
        ],
      })),
    } as Attr;
  });
